pub const VERTEX: &str = r#"#version 150 core
uniform vec2 scale; uniform vec2 uvScale; uniform vec2 uvOffset; out vec2 uv;
void main(){ vec2 p[4]=vec2[4](vec2(-1,-1),vec2(1,-1),vec2(-1,1),vec2(1,1));vec2 t[4]=vec2[4](vec2(0,0),vec2(1,0),vec2(0,1),vec2(1,1));gl_Position=vec4(p[gl_VertexID]*scale,0,1); uv=t[gl_VertexID]*uvScale+uvOffset; }
"#;

pub const FRAGMENT: &str = r#"#version 150 core
uniform sampler2D frameTexture; uniform sampler2D backgroundTexture;uniform sampler2D previousBackgroundTexture;uniform int cdgSidefill; uniform float backgroundOpacity;uniform float previousBackgroundOpacity; uniform float backgroundCrossfadeMix;uniform vec2 cdgPanel; in vec2 uv; out vec4 color;vec4 cdgBlurFill(vec2 p, float panel, float right){float span=right-panel;vec4 acc=vec4(0.0); float wsum=0.0;for(int i=-2;i<=2;i++){ for(int j=-2;j<=2;j++){vec2 o=vec2(float(i)*span*0.025,float(j)*0.035);vec2 c=vec2(clamp(p.x+o.x,panel+span*0.005,right-span*0.005),clamp(p.y+o.y,0.0,1.0));float w=1.0/(1.0+0.06*float(i*i+j*j));acc+=texture(frameTexture,c)*w; wsum+=w; }}return vec4((acc.rgb/wsum)*0.88,1.0);}void main(){if(cdgSidefill==4){vec4 bg=texture(backgroundTexture,uv);vec4 oldBg=texture(previousBackgroundTexture,uv);vec3 rgb=oldBg.rgb*previousBackgroundOpacity*(1.0-backgroundCrossfadeMix)+bg.rgb*backgroundOpacity;color=vec4(rgb,1.0);return;}if(cdgSidefill==5){float panel=cdgPanel.x;float right=cdgPanel.y;float span=right-panel;float lx=panel+span*(3.0/300.0);float rx=panel+span*(297.0/300.0);float ty=6.0/216.0;float by=210.0/216.0;vec4 c0=texture(frameTexture,vec2(lx,ty));vec4 c1=texture(frameTexture,vec2(rx,ty));vec4 c2=texture(frameTexture,vec2(lx,by));vec4 c3=texture(frameTexture,vec2(rx,by));float s0=distance(c0.rgb,c1.rgb)+distance(c0.rgb,c2.rgb)+distance(c0.rgb,c3.rgb);float s1=distance(c1.rgb,c0.rgb)+distance(c1.rgb,c2.rgb)+distance(c1.rgb,c3.rgb);float s2=distance(c2.rgb,c0.rgb)+distance(c2.rgb,c1.rgb)+distance(c2.rgb,c3.rgb);float s3=distance(c3.rgb,c0.rgb)+distance(c3.rgb,c1.rgb)+distance(c3.rgb,c2.rgb);vec3 borderBg=c0.rgb;float best=s0;if(s1<best){borderBg=c1.rgb;best=s1;}if(s2<best){borderBg=c2.rgb;best=s2;}if(s3<best){borderBg=c3.rgb;}lx=panel+span*(12.0/300.0);rx=panel+span*(288.0/300.0);ty=18.0/216.0;by=198.0/216.0;c0=texture(frameTexture,vec2(lx,ty));c1=texture(frameTexture,vec2(rx,ty));c2=texture(frameTexture,vec2(lx,by));c3=texture(frameTexture,vec2(rx,by));s0=distance(c0.rgb,c1.rgb)+distance(c0.rgb,c2.rgb)+distance(c0.rgb,c3.rgb);s1=distance(c1.rgb,c0.rgb)+distance(c1.rgb,c2.rgb)+distance(c1.rgb,c3.rgb);s2=distance(c2.rgb,c0.rgb)+distance(c2.rgb,c1.rgb)+distance(c2.rgb,c3.rgb);s3=distance(c3.rgb,c0.rgb)+distance(c3.rgb,c1.rgb)+distance(c3.rgb,c2.rgb);vec3 tileBg=c0.rgb;best=s0;if(s1<best){tileBg=c1.rgb;best=s1;}if(s2<best){tileBg=c2.rgb;best=s2;}if(s3<best){tileBg=c3.rgb;}vec3 panelBg=tileBg;if(distance(c2.rgb,c3.rgb)<0.10)panelBg=c2.rgb;vec4 fg=texture(frameTexture,uv);float delta=min(distance(fg.rgb,borderBg),min(distance(fg.rgb,tileBg),distance(fg.rgb,panelBg)));if(delta<0.16||(fg.r<0.20&&delta<0.28))discard;color=vec4(fg.rgb,1.0);return;}if(cdgSidefill==3){float span=cdgPanel.y-cdgPanel.x;float x=(uv.x-cdgPanel.x)/max(span,1e-4);float a=smoothstep(0.0,6.0/300.0,x)*smoothstep(0.0,6.0/300.0,1.0-x);vec4 fg=texture(frameTexture,uv); color=vec4(fg.rgb,a); return;}if(cdgSidefill!=0){float panel=cdgPanel.x; float right=cdgPanel.y;if(cdgSidefill==2){ color=cdgBlurFill(uv,panel,right); return; }float lx=panel+(right-panel)*(3.0/300.0);float rx=panel+(right-panel)*(297.0/300.0);float ty=6.0/216.0; float by=210.0/216.0;vec4 c0=texture(frameTexture,vec2(lx,ty));vec4 c1=texture(frameTexture,vec2(rx,ty));vec4 c2=texture(frameTexture,vec2(lx,by));vec4 c3=texture(frameTexture,vec2(rx,by));float s0=distance(c0.rgb,c1.rgb)+distance(c0.rgb,c2.rgb)+distance(c0.rgb,c3.rgb);float s1=distance(c1.rgb,c0.rgb)+distance(c1.rgb,c2.rgb)+distance(c1.rgb,c3.rgb);float s2=distance(c2.rgb,c0.rgb)+distance(c2.rgb,c1.rgb)+distance(c2.rgb,c3.rgb);float s3=distance(c3.rgb,c0.rgb)+distance(c3.rgb,c1.rgb)+distance(c3.rgb,c2.rgb);vec4 bg=c0; float best=s0;if(s1<best){bg=c1;best=s1;} if(s2<best){bg=c2;best=s2;} if(s3<best){bg=c3;}color=bg; return;} color=texture(frameTexture,uv); }
"#;
